const n = $('Yesterday\'s numbers').first().json;
const call = ($('HubSpot: call first').first().json.results || []);
const cold = ($('HubSpot: going cold').first().json.results || []);
const tpl = ($('WhatsApp template quality').first().json.data || []);
const naira = x => '₦' + Math.round(Number(x || 0)).toLocaleString('en-NG');
const day = $now.setZone('Africa/Lagos').toFormat('ccc HH:mm');
const lines = [`☀️ Harvest Lane · health · ${day}`];
lines.push(`Yesterday: ${n.orders} orders · ${n.paid} paid · ${n.delivered} delivered` + (Number(n.refunds_waiting) ? ` · ${n.refunds_waiting} refunds awaiting you` : ''));
lines.push(Number(n.overdue) === 0 ? `All ${n.workflows} workflows ran on schedule ✓` : `⚠️ ${n.overdue} of ${n.workflows} workflows overdue (see watchdog alert)`);
const coldNames = cold.slice(0, 2).map(d => d.properties.dealname).join(', ');
lines.push(`CRM: ${call.length} leads to call first · ${cold.length} deal${cold.length === 1 ? '' : 's'} going cold` + (coldNames ? ` (${coldNames})` : ''));
const weak = tpl.filter(t => t.status !== 'APPROVED' || ['MEDIUM', 'LOW', 'RED', 'YELLOW'].includes(String(t.quality_score?.score || '').toUpperCase()));
lines.push(weak.length ? 'Watch: ' + weak.map(t => `WhatsApp template "${t.name}" ${t.status === 'APPROVED' ? 'quality: ' + String(t.quality_score?.score).toLowerCase() : 'status: ' + t.status} ⚠️`).join(' · ') : 'WhatsApp templates: all approved, quality fine ✓');
lines.push(`AI spend this month: ${naira(n.ai_spend)} of ${naira(n.ai_cap)} cap` + (Number(n.ai_spend) > 0.8 * Number(n.ai_cap) ? ' ⚠️' : ''));
const needs = Number(n.refunds_waiting) > 0 || Number(n.overdue) > 0 || weak.length > 0 || Number(n.alerts_24h) > 0;
lines.push(needs ? (Number(n.refunds_waiting) > 0 ? 'Needs you this morning: refunds waiting.' : 'Needs a look this morning: see the ⚠️ lines.') : 'Nothing needs you before 10 a.m.');
return [{ json: { text: lines.join('\n') } }];
